(function (g) {
  'use strict';
  const table = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
    table[n] = c >>> 0;
  }
  const enc = new TextEncoder();
  const crc32 = (b) => { let c = 0xffffffff; for (const x of b) c = table[(c ^ x) & 0xff] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; };
  const le16 = (n) => new Uint8Array([n & 255, (n >>> 8) & 255]);
  const le32 = (n) => new Uint8Array([n & 255, (n >>> 8) & 255, (n >>> 16) & 255, (n >>> 24) & 255]);
  function join(parts) { const size = parts.reduce((n, p) => n + p.length, 0); const out = new Uint8Array(size); let o = 0; for (const p of parts) { out.set(p, o); o += p.length; } return out; }
  function sig(n) { return le32(n); }
  function Zip(prefix) { this.prefix = prefix || ''; this.files = []; }
  Zip.prototype.folder = function (name) { const z = new Zip(this.prefix + String(name).replace(/^\/+|\/+$/g, '') + '/'); z.files = this.files; return z; };
  Zip.prototype.file = function (name, content) { this.files.push({ name: this.prefix + String(name).replace(/^\/+/, ''), data: enc.encode(String(content)) }); return this; };
  Zip.prototype.generateAsync = async function (opts) {
    const locals = [], centrals = []; let offset = 0;
    for (const f of this.files) {
      const name = enc.encode(f.name), sum = crc32(f.data);
      const local = join([sig(0x04034b50), le16(20), le16(0), le16(0), le16(0), le16(0), le32(sum), le32(f.data.length), le32(f.data.length), le16(name.length), le16(0), name, f.data]);
      locals.push(local);
      const central = join([sig(0x02014b50), le16(20), le16(20), le16(0), le16(0), le16(0), le16(0), le32(sum), le32(f.data.length), le32(f.data.length), le16(name.length), le16(0), le16(0), le16(0), le16(0), le32(0), le32(offset), name]);
      centrals.push(central); offset += local.length;
    }
    const centralSize = centrals.reduce((n, p) => n + p.length, 0);
    const end = join([sig(0x06054b50), le16(0), le16(0), le16(this.files.length), le16(this.files.length), le32(centralSize), le32(offset), le16(0)]);
    const bytes = join([...locals, ...centrals, end]);
    if (opts && opts.type === 'uint8array') return bytes;
    return new Blob([bytes], { type: 'application/zip' });
  };
  g.JSZip = Zip;
})(typeof window !== 'undefined' ? window : globalThis);
